 Q(2, "K", "OWASP Top 10:2021 disusun dari:", "Opini satu orang penulis yang dianggap paling berpengalaman di bidang keamanan aplikasi", "Data pengujian dari beberapa organisasi pada lebih dari 500.000 aplikasi plus survei komunitas", "Iklan produk dari vendor keamanan yang menjadi sponsor proyek OWASP", "Soal ujian sertifikasi keamanan yang dikumpulkan dari peserta setiap tahun", "b", "Halaman pengantar OWASP menjelaskan sumber data itu."),
 Q(2, "K", "Menurut NIST SP 800-115, pengujian intrusif dapat:", "Tidak berdampak apa pun karena pengujian hanya membaca data tanpa mengubah sistem", "Berdampak pada sistem target, termasuk kemungkinan sistem berhenti atau DoS", "Mempercepat sistem target karena beban kerja pengujian membersihkan proses lama", "Menghapus perlunya izin tertulis karena pengujian dianggap bagian dari operasional", "b", "NIST menyebut potensi sistem berhenti tiba-tiba dan kondisi denial of service."),
 Q(2, "K", "NIST SP 800-115 menyediakan templat untuk:", "Rules of Engagement (ROE)", "Resep masakan", "Desain logo", "Daftar harga", "a", "Appendix B memuat templat Rules of Engagement."),
 Q(2, "K", "Menurut CISA BOD 20-01, kebijakan pengungkapan kerentanan harus menyatakan:", "Pengujian apa yang diizinkan atau tidak diizinkan", "Warna situs yang dipakai pada halaman pelaporan kerentanan resmi", "Nama karyawan baru yang bertugas menerima laporan dari peneliti", "Harga tiket acara keamanan yang akan dihadiri oleh tim organisasi", "a", "Kebijakan harus menyebut pengujian yang diizinkan atau secara khusus tidak diizinkan."),
 Q(2, "K", "Target CISA untuk konfirmasi penerimaan laporan kerentanan adalah:", "3 hari kerja", "3 bulan", "1 jam", "1 tahun", "a", "CISA menargetkan acknowledgment dalam 3 hari kerja, penilaian awal 7 hari, dan penyelesaian 90 hari."),
 Q(3, "A", "Broken access control berarti:", "Pengguna dapat bertindak di luar izin yang seharusnya", "Kabel jaringan putus sehingga pengguna tidak dapat membuka aplikasi sama sekali", "Layar perangkat pengguna retak sehingga tombol tidak dapat ditekan dengan benar", "Baterai perangkat habis ketika pengguna sedang mengisi formulir pendaftaran", "a", "OWASP: pengguna dapat bertindak di luar izin yang dimaksudkan."),
 Q(3, "K", "Penyerang mengganti nilai parameter acct pada permintaan sehingga melihat akun orang lain. Kategorinya:", "Broken access control", "Kabel kendur", "Printer macet", "DNS", "a", "Itu contoh parameter tampering pada halaman OWASP A01."),
 Q(3, "K", "Pencegahan broken access control menurut OWASP mencakup:", "Tolak akses secara bawaan kecuali sumber daya publik", "Izinkan semua secara bawaan lalu batasi hanya akses yang dilaporkan bermasalah", "Matikan log akses supaya penyerang tidak dapat membaca catatan aktivitas", "Simpan file .git di web root agar riwayat perubahan mudah ditinjau", "a", "OWASP: deny by default, kecuali sumber daya publik."),
 Q(3, "K", "Prinsip utama mencegah injection menurut OWASP:", "Menjaga data terpisah dari perintah dan kueri", "Menyambung masukan pengguna ke kueri supaya hasil lebih fleksibel", "Mematikan validasi masukan agar pengguna tidak merasa terhambat", "Memperpanjang URL agar parameter lebih sulit ditebak oleh penyerang", "a", "OWASP merangkum pencegahan injection sebagai memisahkan data dari perintah."),
 Q(3, "K", "Pendekatan yang aman untuk kueri SQL dengan masukan pengguna adalah:", "Menyambung string langsung", "Kueri berparameter atau API aman", "Mematikan basis data", "Menyimpan kueri di cookie", "b", "OWASP menganjurkan API aman seperti kueri berparameter atau ORM."),
 Q(3, "K", "Forced browsing adalah:", "Penyerang meminta URL halaman admin secara langsung", "Mengganti kabel jaringan di ruang server agar koneksi lebih stabil", "Memasang antivirus pada server agar berkas berbahaya tidak dapat masuk", "Mengisi formulir pendaftaran dengan benar sebelum menekan tombol kirim", "a", "OWASP menyebut forced browsing ke halaman admin sebagai contoh."),
 Q(3, "A", "Menyambung parameter id langsung ke string SQL bisa menyebabkan:", "Penyerang mengubah kueri dan mengambil semua record", "Halaman dimuat lebih cepat karena kueri langsung dijalankan tanpa pemeriksaan", "Basis data otomatis aman karena mesin SQL membersihkan semua masukan", "Tidak ada dampak karena nilai id biasanya hanya berupa angka biasa", "a", "Contoh OWASP A03: penyerang mengubah id sehingga kueri mengembalikan semua record."),
 Q(4, "K", "Menurut OWASP A07, contoh kelemahan autentikasi adalah:", "Menerima kata sandi bawaan seperti admin/admin", "Memakai MFA untuk setiap akun yang berhak istimewa di aplikasi", "Membatalkan sesi saat logout dan memberi ID sesi baru saat login", "Menampilkan pesan seragam pada formulir pemulihan akun pengguna", "a", "OWASP menyebut kata sandi bawaan atau lemah seperti admin/admin."),
 Q(4, "K", "Mengapa pesan pada pendaftaran dan pemulihan dibuat identik?", "Agar penyerang tidak bisa menebak akun mana yang ada", "Agar pesan lebih singkat dan lebih mudah dibaca oleh pengguna", "Agar tampilan halaman lebih berwarna dan konsisten dengan merek", "Agar server memproses permintaan lebih cepat pada jam sibuk", "a", "OWASP: pesan identik mencegah enumerasi akun."),
 Q(4, "K", "Menurut OWASP A07, ID sesi sebaiknya:", "Ditaruh di URL agar mudah dibagikan antar perangkat pengguna", "Dipakai ulang setelah login supaya pengguna tidak perlu masuk berulang kali", "Diganti baru dan acak setelah login serta dibatalkan saat logout", "Dibuat dari nomor urut agar mudah dilacak oleh administrator sistem", "c", "OWASP: pengelola sesi sisi server menerbitkan ID baru berentropi tinggi setelah login dan membatalkannya saat logout."),
 Q(4, "K", "Ringkasan NIST SP 800-63B Rev. 4: rotasi kata sandi berkala:", "Wajib tiap 30 hari", "Tidak boleh diwajibkan", "Wajib tiap hari", "Wajib bagi semua", "b", "Netwrix mengutip: organisasi tidak boleh mewajibkan rotasi kata sandi berkala."),
 Q(4, "A", "Credential stuffing adalah:", "Memakai daftar pasangan username dan password yang sudah dikenal untuk mencoba login", "Memasang kabel jaringan tambahan untuk menambah jumlah percobaan login per detik", "Membuat password yang sangat panjang supaya sulit ditebak oleh penyerang", "Mengunci pintu ruang server agar tidak ada yang dapat mencoba login", "a", "OWASP menyebut daftar pasangan username dan password yang diketahui."),
 Q(4, "K", "Menurut NIST (ringkasan Netwrix), aturan kompleksitas wajib:", "Dianjurkan", "Dilarang pada Rev. 4", "Wajib", "Tidak dibahas", "b", "Netwrix: SP 800-63B Rev. 4 melarang aturan kompleksitas wajib."),
 Q(4, "K", "Tindakan OWASP terhadap kegagalan login adalah:", "Dicatat dan administrator diberi peringatan", "Diabaikan karena kegagalan login adalah kejadian yang sangat biasa", "Dihapus dari log supaya ukuran berkas catatan tidak terlalu besar", "Disembunyikan dari administrator supaya tidak menimbulkan kepanikan", "a", "OWASP: catat semua kegagalan dan beri peringatan pada serangan."),
 Q(5, "K", "Pengujian aplikasi pendaftaran sekolah sebaiknya dilakukan di:", "Server produksi tanpa pemberitahuan", "Server uji dengan izin tertulis", "Situs sekolah lain", "Jaringan tetangga", "b", "Izin tertulis dan lingkup pada server uji mengikuti prinsip ROE NIST dan prinsip kebijakan pengungkapan."),
 Q(5, "K", "Temuan yang baik menurut panduan pelaporan CISA memuat:", "Deskripsi, lokasi, dampak, langkah reproduksi, dan PoC bila ada", "Hanya nama alat yang dipakai untuk menemukan kerentanan tersebut", "Tebakan tentang siapa pelaku yang mungkin memanfaatkan kerentanan itu", "Logo perusahaan penguji agar laporan tampak lebih meyakinkan bagi klien", "a", "BOD 20-01 meminta informasi itu untuk menganalisis kerentanan."),
 Q(5, "K", "Rekomendasi untuk temuan injection yang paling tepat:", "Gunakan kueri berparameter", "Matikan HTTPS", "Perbanyak halaman", "Ganti warna situs", "a", "Pencegahan OWASP A03 adalah memakai API yang aman seperti kueri berparameter."),
 Q(5, "K", "Rekomendasi untuk temuan 'siswa A bisa membuka data siswa B' adalah:", "Tegakkan kepemilikan record di server", "Sembunyikan tombol ke data siswa lain dari tampilan antarmuka pengguna", "Perpanjang URL supaya identitas record sulit untuk ditebak penyerang", "Ganti font tampilan agar halaman data tidak mudah dikenali penyerang", "a", "OWASP A01: tegakkan kepemilikan record agar pengguna tidak bisa membaca atau mengubah record mana pun."),
 Q(5, "A", "Mengapa data siswa nyata tidak dipakai sebagai bukti?", "Karena BOD 20-01 melarang membuka data pribadi yang ditemukan kepada pihak ketiga, dan bukti secukupnya cukup", "Karena kolom untuk menyimpan data siswa tidak tersedia pada laporan temuan resmi", "Karena data siswa nyata membuat pengujian berjalan lambat dan sulit diulang", "Karena data siswa nyata dianggap kurang menarik untuk dimasukkan ke laporan", "a", "Data pribadi harus dilindungi; buat pengguna uji sendiri."),
 Q(5, "K", "Pengujian yang memicu kondisi DoS paling aman dijadwalkan pada:", "Jam sibuk agar dampaknya langsung terlihat oleh seluruh pengguna", "Jam lalu lintas rendah dan sesuai kesepakatan", "Tanpa jadwal supaya pengujian dapat dimulai kapan saja", "Saat ujian nasional supaya tim sekolah sedang berada di tempat", "b", "NIST menyarankan pengujian yang berisiko DoS dilakukan saat lalu lintas rendah."),
